package au.aumanet.app;
import android.Manifest;import android.app.Activity;import android.content.Intent;import android.net.VpnService;import android.os.*;import androidx.activity.result.ActivityResult;import androidx.lifecycle.Lifecycle;
import com.getcapacitor.*;import com.getcapacitor.annotation.*;
/** Explicit foreground donation/consumer actions. Snapshot never creates networking. */
@CapacitorPlugin(name="InternetSharing",permissions={@Permission(alias="internetNotifications",strings={Manifest.permission.POST_NOTIFICATIONS})})
public final class InternetSharingPlugin extends Plugin{
 private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean destroyed;private Pending pending;
 private static final class Pending{final PluginCall call;final boolean consumer;final long at=SystemClock.elapsedRealtime();InternetSharingController.Pending nativeIntent;Pending(PluginCall call,boolean consumer){this.call=call;this.consumer=consumer;}}
 private boolean foreground(){return !destroyed&&getActivity()!=null&&getActivity().getLifecycle().getCurrentState().isAtLeast(Lifecycle.State.RESUMED);}
 private InternetSharingController controller()throws Exception{return InternetSharingController.get(getContext());}
 private InternetSharingController.Reply reply(PluginCall call){return new InternetSharingController.Reply(){public void done(JSObject state){main.post(()->call.resolve(state));}public void failed(String code){main.post(()->call.reject("Internet sharing request could not be completed",code));}};}
 @PluginMethod public void snapshot(PluginCall call){try{controller().dispatch(()->controller().snapshot(),reply(call));}catch(Exception failed){call.reject("Internet sharing is unavailable","INTERNET_UNAVAILABLE");}}
 @PluginMethod public void share(PluginCall call){begin(call,false);}
 @PluginMethod public void consume(PluginCall call){begin(call,true);}
 private void begin(PluginCall call,boolean consumer){if(!foreground()||pending!=null){call.reject("Open AuMaNET and complete the current request","INTERNET_FOREGROUND_REQUIRED");return;}pending=new Pending(call,consumer);if(Build.VERSION.SDK_INT>=33&&getPermissionState("internetNotifications")!=PermissionState.GRANTED){requestPermissionForAlias("internetNotifications",call,"notifications");return;}dispatch(pending);}
 @PermissionCallback private void notifications(PluginCall call){if(pending!=null&&pending.call==call)dispatch(pending);}
 private void dispatch(Pending request){if(pending!=request)return;if(!foreground()||SystemClock.elapsedRealtime()-request.at>=120000||Build.VERSION.SDK_INT>=33&&getPermissionState("internetNotifications")!=PermissionState.GRANTED){pending=null;request.call.reject("Internet sharing needs a visible Stop notification","INTERNET_PERMISSION_DENIED");return;}try{InternetSharingController owner=controller();if(!request.consumer){pending=null;owner.dispatch(()->owner.share(request.call.getData()),reply(request.call));return;}owner.dispatch(()->{request.nativeIntent=owner.prepare(request.call.getData());return new JSObject();},new InternetSharingController.Reply(){public void done(JSObject ignored){main.post(()->{if(pending!=request||!foreground()){owner.cancelPending(request.nativeIntent,"Internet request cancelled");if(pending==request)pending=null;request.call.reject("Internet request was cancelled","INTERNET_CANCELLED");return;}Intent consent=VpnService.prepare(getContext());if(consent==null){startConsumer(request);return;}try{startActivityForResult(request.call,consent,"vpnConsent");}catch(Exception unavailable){owner.cancelPending(request.nativeIntent,"System VPN permission is unavailable");pending=null;request.call.reject("System VPN permission is unavailable","INTERNET_VPN_PERMISSION");}});}public void failed(String code){main.post(()->{if(pending==request)pending=null;request.call.reject("Selected source is unavailable",code);});}});}catch(Exception failed){pending=null;request.call.reject("Internet sharing is unavailable","INTERNET_UNAVAILABLE");}}
 @ActivityCallback private void vpnConsent(PluginCall call,ActivityResult result){Pending request=pending;if(request==null||request.call!=call)return;if(result.getResultCode()!=Activity.RESULT_OK){try{controller().cancelPending(request.nativeIntent,"VPN permission was declined");}catch(Exception ignored){}pending=null;call.reject("VPN permission was declined","INTERNET_VPN_PERMISSION");return;}main.postDelayed(()->startConsumer(request),100);}
 private void startConsumer(Pending request){if(pending!=request)return;if(!foreground()){if(SystemClock.elapsedRealtime()-request.at<120000){main.postDelayed(()->startConsumer(request),100);return;}try{controller().cancelPending(request.nativeIntent,"Internet request expired");}catch(Exception ignored){}pending=null;request.call.reject("Internet request expired","INTERNET_CANCELLED");return;}pending=null;try{InternetSharingController owner=controller();owner.dispatch(()->owner.consume(request.nativeIntent),new InternetSharingController.Reply(){public void done(JSObject state){reply(request.call).done(state);}public void failed(String code){owner.cancelPending(request.nativeIntent,"Shared internet did not start");reply(request.call).failed(code);}});}catch(Exception failed){request.call.reject("Shared internet could not start","INTERNET_UNAVAILABLE");}}
 @PluginMethod public void stopSharing(PluginCall call){try{long generation=GroupNameMetadata.number(call.getData(),"generation");if(generation<1)throw new IllegalArgumentException();controller().stopSharing(GroupNameMetadata.string(call.getData(),"sessionId"),generation);snapshot(call);}catch(Exception failed){call.reject("Internet sharing is unavailable","INTERNET_UNAVAILABLE");}}
 @PluginMethod public void stopConsuming(PluginCall call){try{long generation=GroupNameMetadata.number(call.getData(),"generation");if(generation<1)throw new IllegalArgumentException();controller().stopConsuming(GroupNameMetadata.string(call.getData(),"sessionId"),generation);snapshot(call);}catch(Exception failed){call.reject("Internet sharing is unavailable","INTERNET_UNAVAILABLE");}}
 @Override protected void handleOnDestroy(){destroyed=true;Pending request=pending;pending=null;if(request!=null){try{controller().cancelPending(request.nativeIntent,"Internet request cancelled");}catch(Exception ignored){}request.call.reject("Internet request cancelled","INTERNET_CANCELLED");}super.handleOnDestroy();}
}

